import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.7nMnW4XS.js";const u=JSON.parse('{"title":"Data-validation + audit tooling","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/data-validation.md","filePath":"reference/tooling/data-validation.md"}'),n={name:"reference/tooling/data-validation.md"};function r(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="data-validation-audit-tooling" tabindex="-1">Data-validation + audit tooling <a class="header-anchor" href="#data-validation-audit-tooling" aria-label="Permalink to &quot;Data-validation + audit tooling&quot;">​</a></h1><p>Reference for Orrery&#39;s <code>scripts/</code> validation and audit suite. <strong>Validators</strong> are fail-closed gates: they exit non-zero on a violation so <code>npm run preflight</code> (and therefore the husky pre-push hook + CI) refuses the push. <strong>Audits</strong> are on-demand diagnostics — most report and exit non-zero, but they&#39;re run by hand, not chained into the gate.</p><p>The gate entry point is <code>npm run validate-data</code>, which runs <code>scripts/validate-data-runner.ts</code> — a parallel runner (<code>Promise.all</code>) that spawns every gating validator concurrently and re-throws the worst exit code. It replaced the old serial <code>&amp;&amp;</code> chain (GH #272) so preflight doesn&#39;t pay wall-clock for independent checks. Adding a new gate = add a <code>Task</code> entry to that runner&#39;s <code>TASKS</code> array.</p><p>Cross-references (not duplicated here): <strong>ADR-069</strong> (overlay-completeness fail-closed contract), <strong>AGENTS.md</strong> §&quot;No-stub validation&quot; + §&quot;Image pipeline — gotchas&quot;, <strong>docs/adr/TA.md</strong> §pipelines.</p><table tabindex="0"><thead><tr><th>Validator</th><th>Gate?</th><th>What it checks</th></tr></thead><tbody><tr><td>validate-data.ts</td><td>yes</td><td>ajv schemas for all <code>static/data/**</code> + ~20 runtime consistency invariants</td></tr><tr><td>validate-diagrams.ts</td><td>yes</td><td>every <code>/science</code> section <code>diagram</code> field has its SVG on disk</td></tr><tr><td>validate-satellites.ts</td><td>yes</td><td>satellites.json schema + gallery + per-locale overlay coverage</td></tr><tr><td>validate-hero-coverage.ts</td><td>yes</td><td>every surface index id has a <code>01.jpg</code> hero (with fallback ladder)</td></tr><tr><td>validate-image-dupes.ts</td><td>yes</td><td>cross/same-surface SHA-256 byte-dupes in <code>static/images/</code></td></tr><tr><td>validate-image-phash-dupes.ts</td><td>yes</td><td>perceptual near-dupes (Hamming ≤ 6) from the phash cache</td></tr><tr><td>validate-gallery-counts.ts</td><td>yes</td><td><code>*-galleries.json</code> counts match on-disk slot reality</td></tr><tr><td>validate-provenance-walker.ts</td><td>yes</td><td>walker schema-sync: no <code>FilePath/undefined</code>, NASA-CDN rows carry <code>nasa_id</code></td></tr><tr><td>validate-allowlist-discipline.ts</td><td>yes</td><td>dupe-allowlist growth vs <code>main</code> stays within budget unless authorized</td></tr><tr><td>validate-credits-bundling.ts</td><td>yes (informational)</td><td><code>/credits</code> bundling integrity; only hard-fails on <code>FilePath/undefined</code></td></tr><tr><td>audit-image-mime.ts</td><td>inline only</td><td><code>.jpg</code> files start with JPEG SOI bytes (same check runs inside validate-data)</td></tr><tr><td>license-allowlist.ts</td><td>n/a (module)</td><td>shared license allowlist consumed by validate-data</td></tr><tr><td>audit-image-usage.ts</td><td>no</td><td>every shipped image is referenced/used somewhere</td></tr><tr><td>audit-report-launches.ts</td><td>no</td><td>launches provenance gaps + unmapped rocket families (HTML report)</td></tr><tr><td>audit-gallery-counts.ts</td><td>no</td><td>gallery counts below threshold (agency-balance diagnostic)</td></tr><tr><td>audit-heroes.ts</td><td>no</td><td>hero-quality rubric across all surfaces (markdown reports)</td></tr><tr><td>audit-fleet-heroes.ts</td><td>no</td><td>fleet hero rubric — <strong>mutates</strong> sidecar + swaps slots</td></tr><tr><td>audit-site-imagery.mjs</td><td>no</td><td>/earth /moon /mars site imagery categorisation (read-only)</td></tr><tr><td>build-audit-report.ts</td><td>no</td><td>image-pipeline HTML report (vision + curation + cost ledger)</td></tr></tbody></table><hr><h2 id="validate-data-ts" tabindex="-1">validate-data.ts <a class="header-anchor" href="#validate-data-ts" aria-label="Permalink to &quot;validate-data.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run validate-data</code> (runs it as one of the parallel tasks); standalone <code>tsx scripts/validate-data.ts</code><strong>What</strong> — The core validator. Compiles ~45 JSON schemas (<code>Ajv({strict:true, strictRequired:false})</code>) and validates every reference file, mission, overlay, fleet entry, science section, launch, audio manifest, etc. Then layers on ~20 runtime invariants the schema can&#39;t express. <strong>When</strong> — automatically in <code>npm run validate-data</code> → preflight → CI. <strong>Fails on</strong> (any of, summed at the end → <code>process.exit(1)</code>): schema violation; cislunar/interplanetary waypoint invariant breach (MET-0 anchor, strictly-increasing, window cap, ≤200 pts); fleet↔mission↔site bidirectional drift + orphan/category mismatch; doc gating-sentence missing (PRD &quot;Why this is a PRD&quot;, RFC &quot;Why this is an RFC&quot;, ADR &quot;&gt; Status ·&quot;); tcm_count drift; provenance license-not-allowed / missing-file / duplicate-path; text-sources + source-logos dupes/missing; link-provenance unknown-source/tracker-survivor/dup/bad-BCP47; launches missing-primary/missing-citation/orphan-launcher-ref; oversized image &gt; 8 MiB workbox cap; <code>.jpg</code> non-JPEG bytes; image-vision/curation malformed; <strong>surface-hotspot Tier-2 consumed-variant missing on disk</strong>; <strong>missing en-US overlay</strong> (earth-objects/fleet/moon-sites/mars-sites/science/fleet-galleries); audio + episode-sources cross-ref breaks. <strong>Gotchas</strong></p><ul><li><strong>Fails CLOSED on a missing en-US overlay</strong> (ADR-069 / GH #83): adding a registry id without its <code>i18n/en-US/.../&lt;id&gt;.json</code> breaks the build here, not just at e2e. Other locales fall back to en-US so only en-US presence is enforced.</li><li>Doc gating-sentence check is scoped to <code>git ls-files</code> (issue #136) — untracked PRD/RFC drafts a parallel agent left don&#39;t block your push; <code>git add</code> them to re-cover. Falls back to a filesystem walk when git metadata is unavailable.</li><li><code>WORKBOX_CACHE_LIMIT_BYTES</code> (8 MiB) must stay in sync with <code>maximumFileSizeToCacheInBytes</code> in <code>vite.config.ts</code> — bump both together. 5–8 MiB is a soft warn band.</li><li>The surface-hotspot variant check mirrors the runtime <code>pickVariant(entry,&#39;thumbnail&#39;)</code> resolve: a hotspot base re-fetched without regenerating its <code>*.1x1.jpg</code> variants 404s at deepest zoom. MANDATORY after any hotspot re-fetch: <code>node scripts/hotspots/regenerate-tier3-variants.mjs &lt;base&gt;.jpg</code>.</li><li>Link-provenance freshness + launches-curation dangling refs are WARN-only (don&#39;t fail the build). <strong>State</strong> — Healthy, the workhorse gate. It has accreted ~20 inline runtime blocks; opportunity: extract the image/overlay blocks into their own runner tasks so they parallelise instead of running serially inside this one process.</li></ul><h2 id="validate-data-helpers-ts" tabindex="-1">validate-data-helpers.ts <a class="header-anchor" href="#validate-data-helpers-ts" aria-label="Permalink to &quot;validate-data-helpers.ts&quot;">​</a></h2><p><strong>Command</strong> — n/a (imported by validate-data.ts) <strong>What</strong> — Pure detector functions for the cross-reference integrity checks: <code>findBidirectionalFleet{Mission,Site}Drift</code>, <code>findProvenanceFailures</code>, <code>findLaunchesMissing{PrimaryProvenance,Citations}</code>, <code>findLaunchesOrphan{LauncherRefs,RocketMappingTargets}</code>. Keeps detection logic pure (testable) while validate-data owns the console templating. <strong>State</strong> — Healthy; the seam that makes the integrity rules unit-testable.</p><h2 id="validate-diagrams-ts" tabindex="-1">validate-diagrams.ts <a class="header-anchor" href="#validate-diagrams-ts" aria-label="Permalink to &quot;validate-diagrams.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run validate-diagrams</code>; also a parallel task inside <code>validate-data</code><strong>What</strong> — Walks every base <code>/science</code> section JSON and asserts any declared <code>diagram</code> field resolves to an SVG at <code>static/diagrams/science/&lt;diagram&gt;</code> (ADR-035). <strong>When</strong> — automatically in <code>npm run validate-data</code>; also exposed standalone. <strong>Fails on</strong> — any <code>diagram</code> reference with no matching SVG on disk. <strong>Gotchas</strong> — skips <code>_index.json</code>; exits 0 (skip) when <code>static/data/science/</code> is absent. <strong>State</strong> — Healthy, narrow scope.</p><h2 id="validate-satellites-ts" tabindex="-1">validate-satellites.ts <a class="header-anchor" href="#validate-satellites-ts" aria-label="Permalink to &quot;validate-satellites.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-satellites.ts</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Schema + coverage for the natural-satellite layer (#304): required fields + library tier/kind enums on <code>satellites.json</code>, <code>satellite-galleries.json</code> coverage, and a per-locale overlay file for every satellite × locale. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — missing required field, duplicate id, invalid library tier/kind, missing gallery entry, or a missing overlay file in any locale. <strong>Gotchas</strong> — orphan gallery entries and missing per-locale <code>satellites/</code> dirs are WARN, not fail. Skips <code>packed-lines</code>. <strong>State</strong> — Healthy.</p><h2 id="validate-hero-coverage-ts" tabindex="-1">validate-hero-coverage.ts <a class="header-anchor" href="#validate-hero-coverage-ts" aria-label="Permalink to &quot;validate-hero-coverage.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-hero-coverage.ts</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Walks every surface index (missions/fleet/moon-sites/mars-sites/earth-objects/planets) and verifies a <code>01.jpg</code> hero exists, following the same cross-surface fallback ladder as the runtime gallery loader. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — any id with no hero on disk AND no fallback hit AND not in that surface&#39;s <code>KNOWN_*_GAPS</code> allowlist. <strong>Gotchas</strong> — all <code>KNOWN_*_GAPS</code> sets are currently empty (#342 cleared the cruise-phase backlog). The fallback ladder is bidirectional (surface↔missions↔fleet) so a byte-dedup pass that dropped a redundant copy doesn&#39;t false-flag. Adding an id to a gap set requires a real fetch + a <code>docs/provenance/image-hero-inventory.md</code> entry. <strong>State</strong> — Healthy / current. Coupled to the runtime loader&#39;s ladder — keep <code>FALLBACK_LADDER</code> in sync with <code>src/lib/data.ts</code>.</p><h2 id="validate-image-dupes-ts" tabindex="-1">validate-image-dupes.ts <a class="header-anchor" href="#validate-image-dupes-ts" aria-label="Permalink to &quot;validate-image-dupes.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-image-dupes.ts</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — SHA-256-hashes every base <code>.jpg</code> in <code>static/images/</code> and fails on any 2+ files sharing bytes (cross-surface OR same-surface) unless the 8-char prefix is in the inline <code>ALLOWLIST</code>. Exports <code>ALLOWLIST</code> for the phash validator to import. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — any un-allowlisted byte-dupe group. <strong>Gotchas</strong> — skips <code>.1x1/.4x3/.16x9</code> variant crops (only base images). <code>main()</code> runs only when invoked directly, so the phash sibling can import <code>ALLOWLIST</code> without triggering a scan. The allowlist is large and growing — every legitimate editorial cross-surface reuse needs a one-line prefix + comment; this is the duplicate-manifest-entry trap that <code>validate-allowlist-discipline.ts</code> polices. <strong>State</strong> — Healthy but the allowlist is heavy (~250 entries). Each is human-justified; growth is gated.</p><h2 id="validate-image-phash-dupes-ts" tabindex="-1">validate-image-phash-dupes.ts <a class="header-anchor" href="#validate-image-phash-dupes-ts" aria-label="Permalink to &quot;validate-image-phash-dupes.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-image-phash-dupes.ts</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Reads the <code>static/data/image-phashes.json</code> cache (built by <code>compute-phash.ts</code>), does an O(n²) Hamming scan, fails on any pair with d ≤ 6 not in <code>INLINE_ALLOWLIST</code> + <code>phash-baseline-allowlist.json</code>. Auto-skips byte-identical pairs already signed off in the byte-allowlist. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — any un-allowlisted near-dupe at d ≤ 6. <strong>Gotchas</strong> — <strong>phash cache staleness</strong>: this reads a precomputed cache, not live pixels — re-run <code>compute-phash.ts</code> after image changes or the scan validates stale state. Threshold 6 is hand-tuned to the current corpus; it catches re-encodes/crops, NOT &quot;same subject different shoot&quot; (those land at d≈25-40). The dual-allowlist (inline categorised + JSON baseline snapshot) means a near-dupe can be silenced in two places. <strong>State</strong> — Healthy; depends on cache freshness being maintained out-of-band.</p><h2 id="validate-gallery-counts-ts" tabindex="-1">validate-gallery-counts.ts <a class="header-anchor" href="#validate-gallery-counts-ts" aria-label="Permalink to &quot;validate-gallery-counts.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-gallery-counts.ts</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Asserts <code>fleet-galleries.json</code> + <code>mission-galleries.json</code> counts equal the on-disk count of <code>NN.jpg</code> base slots per id. The count IS the contract the gallery loader uses to enumerate slot URLs. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — any id where manifest count ≠ disk count (over → 404, under → silently-hidden images). <strong>Gotchas</strong> — only counts base <code>\\d{2}\\.jpg</code>; covers fleet + mission manifests only (satellite/site/planet count-checks live elsewhere — see audit-image-usage&#39;s broader manifest map). <strong>State</strong> — Healthy. Opportunity: it covers 2 of the ~11 count manifests <code>audit-image-usage.ts</code> knows about; the others aren&#39;t gated against disk here.</p><h2 id="validate-provenance-walker-ts" tabindex="-1">validate-provenance-walker.ts <a class="header-anchor" href="#validate-provenance-walker-ts" aria-label="Permalink to &quot;validate-provenance-walker.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-provenance-walker.ts [--manifest=...]</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Enforces the build-image-provenance walker&#39;s schema-sync contract: no entry has <code>image_url</code> ending <code>Special:FilePath/undefined</code>, and every NASA-CDN-referencing entry carries a non-null <code>nasa_id</code>. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — any <code>FilePath/undefined</code> survivor or NASA-CDN row with null <code>nasa_id</code>. <strong>Gotchas</strong> — defends against two specific historical walker bugs (Slice A v3); the <code>FilePath/undefined</code> check is also re-asserted defensively in <code>validate-credits-bundling.ts</code>. <strong>State</strong> — Healthy, tightly scoped to known regressions.</p><h2 id="validate-allowlist-discipline-ts" tabindex="-1">validate-allowlist-discipline.ts <a class="header-anchor" href="#validate-allowlist-discipline-ts" aria-label="Permalink to &quot;validate-allowlist-discipline.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-allowlist-discipline.ts [--base=main --max=5]</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Diffs the dupe-allowlist entries (byte + phash) against <code>origin/main</code>/<code>main</code> and fails when more than <code>MAX_AUTOLAND</code> (5) new entries land on the branch without an <code>ALLOWLIST_AUTHORIZED:</code> token in a commit message. Stops the &quot;silence the build by padding the allowlist&quot; pattern that shipped 707 bad swaps. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — net-new allowlist entries &gt; max AND no <code>ALLOWLIST_AUTHORIZED:</code> token in branch commits. <strong>Gotchas</strong> — skips silently when no baseline ref is resolvable (initial setup / shallow clone). Authorization is a literal commit-message token after curator review, not a code change. <strong>State</strong> — Healthy; the meta-gate over the two dupe validators.</p><h2 id="validate-credits-bundling-ts" tabindex="-1">validate-credits-bundling.ts <a class="header-anchor" href="#validate-credits-bundling-ts" aria-label="Permalink to &quot;validate-credits-bundling.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>tsx scripts/validate-credits-bundling.ts [--top=N --fail-on-split]</code> (parallel task in <code>validate-data</code>) <strong>What</strong> — Mirrors <code>src/lib/credits-grouping.ts</code> to report how <code>/credits</code> collapses provenance entries into bundles: cross-route reuse, cross-source &quot;split&quot; bundles. Defensively re-checks for <code>FilePath/undefined</code>. <strong>When</strong> — automatically in <code>npm run validate-data</code>. <strong>Fails on</strong> — <code>FilePath/undefined</code> survivors (always); cross-source splits only when <code>--fail-on-split</code> is passed (off in the gate). <strong>Gotchas</strong> — <code>agencyToSourceId</code> + <code>SOURCE_TYPE_TO_ID</code> are hand-mirrored from <code>credits-grouping.ts</code>; if either drifts, split detection becomes inaccurate (still informative). In the gate it&#39;s effectively a <code>FilePath/undefined</code> guard + a report. <strong>State</strong> — Healthy but mostly informational in CI. Opportunity: the manual mirror of the grouping logic is a drift risk — import the real functions instead.</p><h2 id="audit-image-mime-ts" tabindex="-1">audit-image-mime.ts <a class="header-anchor" href="#audit-image-mime-ts" aria-label="Permalink to &quot;audit-image-mime.ts&quot;">​</a></h2><p><strong>Command</strong> — <code>npx tsx scripts/audit-image-mime.ts</code> (report) · <code>--repair</code> (re-encode in place) · <code>--quiet</code><strong>What</strong> — Walks <code>static/images/**/*.jpg</code> and verifies each starts with the JPEG SOI marker (<code>ff d8 ff</code>). GH #251: 110 fleet files had <code>.jpg</code> extensions but raw PNG bytes, silently breaking Anthropic vision scoring. <strong>When</strong> — the <strong>check</strong> runs inline inside <code>validate-data</code> (so it gates); this standalone script is the on-demand reporter + repair tool. <strong>Fails on</strong> — any <code>.jpg</code>/<code>.jpeg</code> whose first 3 bytes aren&#39;t JPEG. <strong>Gotchas</strong> — <code>--repair</code> re-encodes via <code>coerceToJpeg()</code> then re-verifies. Fetchers should call <code>coerceToJpeg()</code> to prevent regression. Browsers + sharp sniff and render anyway, so the mismatch is otherwise invisible. <strong>State</strong> — Healthy; the gate copy and the standalone repair tool share <code>lib/image-bytes.ts</code>.</p><h2 id="license-allowlist-ts" tabindex="-1">license-allowlist.ts <a class="header-anchor" href="#license-allowlist-ts" aria-label="Permalink to &quot;license-allowlist.ts&quot;">​</a></h2><p><strong>Command</strong> — n/a (module) <strong>What</strong> — Canonical license allowlist for image + text provenance (ADR-046 Milestone C). Exports <code>isAllowedLicense</code>, <code>getAllowlistEntry</code>, <code>normaliseLicenseShortName</code>. Includes the deliberate non-Western-agency precedents (CNSA-EDU, ISRO-EDU, JAXA-OPEN, SpaceIL-EDU) and <code>Orrery-Original</code> for in-house prose. <strong>When</strong> — consumed by validate-data&#39;s provenance + text-sources gates. <strong>Gotchas</strong> — anything not in the allowlist AND not waived in <code>license-waivers.json</code> fails closed. Prefer extending the allowlist (with a rationale) over filing a waiver. <strong>State</strong> — Healthy / current; the single source of truth for license stewardship.</p><hr><h2 id="audit-family-on-demand-—-not-in-validate-data" tabindex="-1">Audit family (on-demand — not in <code>validate-data</code>) <a class="header-anchor" href="#audit-family-on-demand-—-not-in-validate-data" aria-label="Permalink to &quot;Audit family (on-demand — not in `validate-data`)&quot;">​</a></h2><h3 id="audit-image-usage-ts" tabindex="-1">audit-image-usage.ts <a class="header-anchor" href="#audit-image-usage-ts" aria-label="Permalink to &quot;audit-image-usage.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audit:images</code> · <code>npm run audit:images -- --write-approved</code><strong>What</strong> — Proves the RFC-029 invariant: every shipped image under <code>static/images/</code> (minus gitignored <code>_staging/</code>) is referenced by a display manifest, source code, a gallery count-cap, a hero slot, or is a body/card/hotspot. <code>--write-approved</code> (re)derives <code>image-approved.json</code> from the same classifier. <strong>When</strong> — on-demand. Strong candidate to promote into the gate (it&#39;s the broadest coverage check and already exits 1 on orphans). <strong>Fails on</strong> — any UNKNOWN orphan not in <code>ALLOWED_ORPHANS</code> (currently empty). <strong>Gotchas</strong> — variant-aware (a used base covers all its crops). <code>BOOKKEEPING</code> regex excludes all-path manifests so they don&#39;t mark everything &quot;referenced&quot;. Knows all ~11 gallery count manifests — broader than the gated <code>validate-gallery-counts.ts</code>. <strong>State</strong> — Current; the natural next promotion into <code>validate-data</code>.</p><h3 id="audit-report-launches-ts" tabindex="-1">audit-report-launches.ts <a class="header-anchor" href="#audit-report-launches-ts" aria-label="Permalink to &quot;audit-report-launches.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audit:launches</code> (also <code>npm run docker:audit-launches</code>) <strong>What</strong> — Writes gitignored <code>static/audit-report-launches.html</code>: provenance gaps (rows where agency-direct returned nothing, source <code>ll2</code>), unmapped rocket families, tier-reason distribution (RFC-023 §10). <strong>When</strong> — on-demand, after <code>npm run fetch:launches</code>. <strong>State</strong> — Current; pure reporter, never exits non-zero.</p><h3 id="audit-gallery-counts-ts" tabindex="-1">audit-gallery-counts.ts <a class="header-anchor" href="#audit-gallery-counts-ts" aria-label="Permalink to &quot;audit-gallery-counts.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npx tsx scripts/audit-gallery-counts.ts [--json] [--non-nasa] [--threshold N]</code><strong>What</strong> — Reports mission + fleet gallery counts below a threshold (default 3), grouped by agency — surfaces non-NASA coverage gaps for agency balance. <strong>When</strong> — on-demand. Exits non-zero when any entry is below threshold (a diagnostic, not wired into the gate). <strong>State</strong> — Current.</p><h3 id="audit-heroes-ts" tabindex="-1">audit-heroes.ts <a class="header-anchor" href="#audit-heroes-ts" aria-label="Permalink to &quot;audit-heroes.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npx tsx scripts/audit-heroes.ts [--surface=&lt;name&gt;] [--list-clean]</code><strong>What</strong> — Applies the hero-quality rubric (URL deny-list, subject deny-list, vision category/score rules, subject↔id mismatch) across all 8 surfaces and writes <code>docs/provenance/&lt;surface&gt;-hero-audit.md</code> with swap proposals / needs-sourcing / accepted-overrides. Read-only on manifests; does not apply swaps. <strong>When</strong> — on-demand, no API calls. <strong>Gotchas</strong> — <code>&lt;surface&gt;-hero-overrides.json</code> wins over rubric output silently; the report lists overrides to keep them reviewable. <strong>State</strong> — Current; the quality counterpart to the coverage gate.</p><h3 id="audit-fleet-heroes-ts" tabindex="-1">audit-fleet-heroes.ts <a class="header-anchor" href="#audit-fleet-heroes-ts" aria-label="Permalink to &quot;audit-fleet-heroes.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npx tsx scripts/audit-fleet-heroes.ts</code><strong>What</strong> — Older, fleet-only hero auditor. <strong>Mutates</strong>: applies auto-swaps to disk + rewrites <code>fleet-image-sources.json</code>, writes <code>docs/provenance/fleet-hero-audit.md</code>. <code>ACCEPTED_OVERRIDES</code> holds the no-clean-photo cohort (Energia, Tiangong-2, Salyut-7, Soyuz 7K-OK). <strong>When</strong> — on-demand only — it writes files, so never in CI. <strong>Gotchas</strong> — superseded in scope by the read-only <code>audit-heroes.ts</code>; this one still has the destructive swap path. Run deliberately. <strong>State</strong> — Needs-attention — overlaps <code>audit-heroes.ts</code> (which is read-only + multi-surface). Candidate for retirement once its swap utility is folded into a non-destructive apply step.</p><h3 id="audit-site-imagery-mjs" tabindex="-1">audit-site-imagery.mjs <a class="header-anchor" href="#audit-site-imagery-mjs" aria-label="Permalink to &quot;audit-site-imagery.mjs&quot;">​</a></h3><p><strong>Command</strong> — <code>node scripts/audit-site-imagery.mjs</code><strong>What</strong> — Categorises every /earth /moon /mars site by own-vs-mission-vs-fleet hero byte-size into KEEP_OWN / DELETE_OWN_USE_MISSION / FALLBACK_OK / HAND_SOURCE etc. Writes <code>/tmp/site-image-audit.json</code>. Read-only. <strong>When</strong> — on-demand. <strong>State</strong> — Current; a one-shot triage helper (size-heuristic, not vision-based).</p><h3 id="build-audit-report-ts" tabindex="-1">build-audit-report.ts <a class="header-anchor" href="#build-audit-report-ts" aria-label="Permalink to &quot;build-audit-report.ts&quot;">​</a></h3><p><strong>Command</strong> — <code>npx tsx scripts/build-audit-report.ts [--threshold N]</code><strong>What</strong> — Renders gitignored <code>static/audit-report.html</code> from <code>image-curation.json</code> + <code>image-vision.json</code> + <code>cost-ledger.json</code>: flagged deny-list, low-score images, fallback/rejected, recent scoring runs + total spend (PRD-018 M6 / RFC-022 §8). <strong>When</strong> — on-demand. <strong>State</strong> — Current; the image-pipeline operator dashboard.</p>',49)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
